IF ((M1111 = TRUE) OR (M699 = TRUE)) THEN
MACHINE_STATUS_LOG := 2;
ELSIF ((Y23=TRUE)AND(M1111 = FALSE)) THEN
MACHINE_STATUS_LOG := 1;
END_IF;
IF (MACHINE_STATUS_LOG=2 AND Interlock_Bit= 0) THEN
FIFO_SIZE_LOG:= 51;
FIFO_1_LOG:=(FIFO_VALUE_LOG);
FIFO_2_LOG:=(FIFO_VALUE_MIN_LOG);
FOR I:= 1 TO UINT_TO_DINT(FIFO_SIZE_LOG-1)BY 1 DO
FIFO_VALUE_LOG[I+1]:=FIFO_1_LOG[I];
FIFO_VALUE_MIN_LOG[I+1]:=FIFO_2_LOG[I];
END_FOR;
FIFO_VALUE_LOG[1]:= (DOFF_TIME_LOG.SECONDS);
FIFO_VALUE_MIN_LOG[1]:= (DOFF_TIME_LOG.MINUTES);
END_IF;
IF(Interlock_Bit) THEN
FIFO_VALUE_LOG[1]:= (DOFF_TIME_LOG.SECONDS);
FIFO_VALUE_MIN_LOG[1]:= (DOFF_TIME_LOG.MINUTES);
Doff_Time_Log_Reset:=0;
ELSE
Doff_Time_Log_Reset:=1;
END_IF;
DOFF_TIME_LOG(START:=(MACHINE_STATUS_LOG = 2) , RESET:=Doff_Time_Log_Reset);
