Interlock_Bit := 0;
END_IF
IF (LAP_BUILD_TIME_RESET) THEN
Interlock_Bit_Lap:=0;
ELSE
Interlock_Bit_Lap:=1;
END_IF
IF(EDGEPOS(M1111))THEN
IF (LAP_BUILD_TIME_RESET=FALSE AND Interlock_Bit_Lap) THEN
FIFO_SIZE_LAP_BUILD_LOG:= 51;
