FIFO_VALUE_SPOOL_UP_LOG[1]:= (SPOOL_UP_TIME_LOG.SECONDS);
FIFO_VALUE_MIN_SPOOL_UP_LOG[1]:= (SPOOL_UP_TIME_LOG.MINUTES);
