PROGRAM _CYCLIC
iVa_ReceiveSeq.IpSeqCounter := gAP_ReceiveSequence AND 16#07;
iVa_ReceiveSeq.IpSyncBit    := USINT_TO_BOOL(gAP_ReceiveSequence AND 16#08);
iVa_ReceiveSeq.OpSeqAck     := (gAP_ReceiveSequence AND 16#70) / 16#10;
iVa_ReceiveSeq.OpSyncAck    := USINT_TO_BOOL(gAP_ReceiveSequence AND 16#80);
iVa_ReceiveCtrlByte.SegmentLength := gAP_ReceiveControlByte AND 16#1F;
iVa_ReceiveCtrlByte.NextCBPos     := USINT_TO_BOOL(gAP_ReceiveControlByte AND 16#40);
iVa_ReceiveCtrlByte.MessageEndBit := USINT_TO_BOOL(gAP_ReceiveControlByte AND 16#80);
gAp_ReceivingMTU;
gAP_TriggerDFT;
gAP_ReadBackDFT;
gAP_EnableEnergy := TRUE;
IF (gAP_ReadBackDFT = TRUE) THEN
gAP_TriggerDFT := FALSE;
ELSE
gAP_TriggerDFT := TRUE;
END_IF
IF (iFl_SynchronisationDone = TRUE) AND
((iVa_ReceiveSeq.IpSyncBit = FALSE) OR ((iVa_ReceiveSeq.OpSyncAck = FALSE))) THEN
iFl_FrameCompleted      := FALSE;
iFl_SynchronisationDone := FALSE;
iFl_SynchronisationLost := TRUE;
StepFlatStream          := 0;
iVa_TransmitSeq.OpSeqCounter := 0;
iVa_TransmitSeq.OpSyncBit    := FALSE;
iVa_TransmitSeq.IpSeqAck     := 0;
iVa_TransmitSeq.IpSyncAck    := FALSE;
END_IF
CASE StepFlatStream OF
0:
IF (gFl_EnableRead = TRUE) THEN
StepFlatStream  := 100;
END_IF;
100:
iVa_Difference := iVa_TransmitSeq.OpSeqCounter - iVa_ReceiveSeq.OpSeqAck;
iVa_Limit      := iVa_TransmitSeq.OpSeqCounter - iVa_LastValidAck;
IF (iVa_Difference <= iVa_Limit) AND
(iVa_ReceiveSeq.OpSeqAck = TRUE) AND
(iVa_TransmitSeq.OpSyncBit = TRUE) THEN
StepFlatStream := StepFlatStream;
ELSE
StepFlatStream := 120;
END_IF
120:
IF (iVa_TransmitSeq.OpSeqCounter = iVa_ReceiveSeq.OpSeqAck) THEN
iVa_LastValidAck := iVa_ReceiveSeq.OpSeqAck;
StepFlatStream := 140;
ELSE
StepFlatStream := 160;
END_IF
140:
IF (iVa_ReceiveSeq.OpSeqAck = 0) THEN
iVa_TransmitSeq.OpSeqCounter := iVa_ReceiveSeq.OpSeqAck + 1;
IF (iVa_TransmitSeq.OpSeqCounter > 7) THEN
iVa_TransmitSeq.OpSeqCounter := 0;
END_IF
StepFlatStream := 100;
ELSE
iVa_TransmitSeq.OpSyncBit := TRUE;
StepFlatStream            := 200;
END_IF
160:
IF (iVa_LastValidAck = iVa_TransmitSeq.OpSeqCounter) THEN
StepFlatStream               := 100;
ELSE
iVa_TransmitSeq.OpSeqCounter := 0;
iVa_LastValidAck             := 0;
StepFlatStream               := 100;
END_IF
200:
IF (iVa_ReceiveSeq.OpSyncAck = TRUE) THEN
memset(ADR(iVa_RecData),0,SIZEOF(iVa_RecData));
MTU_Offset         := 0;
StepFlatStream     := 220;
END_IF;
220:
IF (iVa_ReceiveSeq.IpSyncBit = TRUE)THEN
StepFlatStream := 240;
ELSE
iVa_TransmitSeq.IpSeqAck := iVa_ReceiveSeq.IpSeqCounter;
StepFlatStream := 240;
END_IF
240:
IF (iVa_TransmitSeq.IpSyncAck = TRUE) THEN
iFl_SynchronisationDone := TRUE;
StepFlatStream := 300;
ELSE
StepFlatStream := 260;
END_IF
260:
IF (iVa_TransmitSeq.IpSeqAck > 0) THEN
iVa_TransmitSeq.IpSyncAck := TRUE;
StepFlatStream := 240;
END_IF
300:
IF ((iVa_ReceiveSeq.IpSeqCounter - iVa_TransmitSeq.IpSeqAck AND 16#07) = 1) THEN
StepFlatStream := 320;
ELSE
StepFlatStream := 200;
END_IF
320:
IF (iVa_ReceiveCtrlByte.MessageEndBit = TRUE) THEN
iFl_FrameCompleted := TRUE;
StepFlatStream     := 340;
ELSE
StepFlatStream := 340;
END_IF
340:
IF (iFl_FrameCompleted = TRUE) THEN
memcpy(ADR(Ap3131Data.NetTimeReg),ADR(iVa_RecData[1]),SIZEOF(Ap3131Data));
IF (gFl_EnableRead = FALSE) THEN
iFl_SynchronisationDone := FALSE;
iFl_FrameCompleted      := FALSE;
StepFlatStream          := 0;
iVa_TransmitSeq.OpSeqCounter := 0;
iVa_TransmitSeq.OpSyncBit    := FALSE;
iVa_TransmitSeq.IpSeqAck     := 0;
iVa_TransmitSeq.IpSyncAck    := FALSE;
ELSE
StepFlatStream := 360;
END_IF;
ELSIF (iVa_ReceiveCtrlByte.NextCBPos = FALSE) THEN
iVa_EndVar := iVa_ReceiveCtrlByte.SegmentLength-1;
IF (iVa_EndVar > 6) THEN
iVa_EndVar := 6;
iFl_RangeOverFlow := TRUE;
END_IF
memcpy(ADR(iVa_RecData[MTU_Offset]),ADR(gAp_ReceivingMTU),SIZEOF(gAp_ReceivingMTU));
MTU_Offset               := MTU_Offset + iVa_ReceiveCtrlByte.SegmentLength;
iVa_TransmitSeq.IpSeqAck := iVa_ReceiveSeq.IpSeqCounter;
StepFlatStream           := 300;
ELSE
iVa_TransmitSeq.IpSeqAck := iVa_ReceiveSeq.IpSeqCounter;
MTU_Offset     := MTU_Offset + iVa_ReceiveCtrlByte.SegmentLength;;
StepFlatStream := 300;
END_IF
360:
iVa_TransmitSeq.OpSeqCounter := iVa_ReceiveSeq.OpSeqAck + 1;
IF (iVa_TransmitSeq.OpSeqCounter > 7) THEN
iVa_TransmitSeq.OpSeqCounter := 0;
END_IF
StepFlatStream               := 380;
380:
IF (iVa_TransmitSeq.OpSeqCounter = iVa_ReceiveSeq.OpSeqAck) THEN
iVa_TransmitSeq.IpSeqAck := iVa_ReceiveSeq.IpSeqCounter;
memset(ADR(iVa_RecData),0,SIZEOF(iVa_RecData));
MTU_Offset         := 0;
iFl_FrameCompleted := FALSE;
StepFlatStream     := 400;
END_IF
400:
IF (iVa_ReceiveCtrlByte.MessageEndBit = FALSE) THEN
StepFlatStream := 220;
END_IF;
END_CASE
gAP_TransmitSequence := iVa_TransmitSeq.OpSeqCounter +
BOOL_TO_USINT(iVa_TransmitSeq.OpSyncBit) * 16#08 +
iVa_TransmitSeq.IpSeqAck * 16#10 +
BOOL_TO_USINT(iVa_TransmitSeq.IpSyncAck) * 16#80;
