END_PROGRAM
PROGRAM _CYCLIC
IF (HMI_IP_ADDR = '')THEN
HMI_IP_ADDR := 'Enter ip Adress';
END_IF
IF (HMI_start_ping = TRUE) AND (HMI_IP_ADDR <> '')THEN
HMI_PING_STATES_VISU := FALSE;
IcmpPing_0(enable := TRUE, pHost := ADR(HMI_IP_ADDR), timeout := 5);
IF (IcmpPing_0.status = 0) THEN
ping_error_count := 0;
HMI_PING_STATES[ping_try] := 1;
HMI_PING_STATES_COLOR[ping_try] := 10;
ping_try := ping_try + 1;
ELSIF (IcmpPing_0.status = ERR_FUB_BUSY) THEN
ping_error_count := ping_error_count + 1;
ELSIF ((IcmpPing_0.status >= 32750) OR (IcmpPing_0.status <= 65534) OR (ping_error_count > 10))THEN
ping_error_count := 0;
HMI_PING_STATES[ping_try] := 2;
HMI_PING_STATES_COLOR[ping_try] := 51;
ping_try := ping_try + 1;
END_IF
IF (ping_try >= 3) THEN
HMI_start_ping := FALSE;
HMI_PING_STATES_HIDE := TRUE;
END_IF
END_IF
TON_hide_ping_state(IN := HMI_PING_STATES_HIDE, PT := t#5s);
IF (TON_hide_ping_state.Q) THEN
HMI_PING_STATES_HIDE := FALSE;
nxt_adr := memset(ADR(HMI_PING_STATES),0,5);
nxt_adr := memset(ADR(HMI_PING_STATES_COLOR),232,5);
HMI_PING_STATES_VISU := TRUE;
ping_try := 0;
END_IF
END_PROGRAM

